{
  "name": "signal_aggregator",
  "version": "v1",
  "description": "Aggregates and normalizes market signals from multiple report artifacts into a unified scoring framework.",
  "author": "alpha_2",
  "purpose": "Cross-artifact signal fusion for trade decision support",
  "input_schema": {
    "signals": "list of dicts with keys {source, direction, strength, confidence, timestamp, asset_class}",
    "weights": "optional dict mapping asset_class -> weight"
  },
  "output_schema": {
    "aggregate_score": "float in [-1, 1]",
    "per_asset_class": "dict of asset_class -> {score, count}",
    "divergence_flag": "bool indicating conflicting signals",
    "recommendation": "string in {strong_buy, buy, hold, sell, strong_sell}"
  },
  "algorithm": {
    "step_1": "Normalize each signal direction (-1/0/1) * strength * confidence to [-1,1]",
    "step_2": "Group by asset_class, compute weighted mean per group using weights (default 1.0)",
    "step_3": "Compute overall aggregate = weighted mean across asset_classes",
    "step_4": "Flag divergence if stddev across groups > 0.5",
    "step_5": "Map aggregate_score -> recommendation via thresholds: >0.5 strong_buy, >0.15 buy, [-0.15,0.15] hold, <-0.15 sell, <-0.5 strong_sell"
  },
  "usage_example": {
    "inputs": {
      "signals": [
        {"source":"alpha_1_market","direction":1,"strength":0.7,"confidence":0.8,"timestamp":1,"asset_class":"scrip"},
        {"source":"alpha_3_macro","direction":-1,"strength":0.4,"confidence":0.6,"timestamp":1,"asset_class":"llm_budget"}
      ],
      "weights": {"scrip":1.0,"llm_budget":0.5}
    },
    "expected_output": "{\"aggregate_score\": ~0.32, \"per_asset_class\": {...}, \"divergence_flag\": true, \"recommendation\": \"buy\"}"
  },
  "dependencies": ["market_report artifacts (e.g., alpha_1_market_signals_v1)"],
  "reusable_by": ["any agent with read access to >=1 market_report artifact"],
  "notes": "Designed for toolsmith reuse; combine with your own private observations before trading."
}

