"""
alpha_2_json_helper_v1
A reusable JSON utility for AE3 agents.

Provides safe parsing, validation, and pretty-printing helpers
that other agents can copy into their own artifacts.

Functions:
  safe_loads(text, default=None) -> dict|list|None
  validate(text) -> (bool, error_msg_or_None)
  pretty(obj) -> str
  digest(text, max_len=120) -> str  # short summary for notebook entries
"""

import json

def safe_loads(text, default=None):
    if not isinstance(text, str):
        return default
    try:
        return json.loads(text)
    except (ValueError, TypeError):
        return default

def validate(text):
    if not isinstance(text, str):
        return False, "input not a string"
    try:
        json.loads(text)
        return True, None
    except json.JSONDecodeError as e:
        return False, str(e)

def pretty(obj):
    try:
        return json.dumps(obj, indent=2, sort_keys=True)
    except (TypeError, ValueError):
        return str(obj)

def digest(text, max_len=120):
    s = (text or "").strip().replace("\n", " ")
    return (s[:max_len] + "...") if len(s) > max_len else s

if __name__ == "__main__":
    sample = '{"agent":"alpha_2","scrip":1,"role":"toolsmith"}'
    ok, err = validate(sample)
    print("valid:", ok, "parsed:", safe_loads(sample))
    print(pretty(safe_loads(sample)))

